// Reproduce the issue and show how to generate fpss-based thumbnails
// Prereqs: npm install puppeteer sharp

const puppeteer = require('puppeteer');
const sharp = require('sharp');

;(async () => {
  // 1. Launch headless Chrome and navigate to the target page
  const browser = await puppeteer.launch();
  const page = await browser.newPage();
  await page.goto('https://apache.org/', {waitUntil: 'networkidle2'});

  // 2. Find all <img> without explicit width & height
  const elements = await page.$$eval('img:not([width])[not([height])]', els =>
    els.map(el => {
      const {x, y, width, height} = el.getBoundingClientRect();
      return {src: el.src, x, y, width, height};
    })
  );

  if (!elements.length) {
    console.log('No missing-width/height images found.');
    await browser.close();
    return;
  }

  // 3. Capture a full-page screenshot
  const fullPng = await page.screenshot({fullPage: true});

  // 4. For each failing image, crop out its rect from the fpss,
  //    resize to 200px wide (or any thumbnail size), and embed.
  for (const el of elements) {
    // round to nearest pixel
    const left = Math.round(el.x);
    const top = Math.round(el.y);
    const w = Math.round(el.width);
    const h = Math.round(el.height);

    // extract & resize
    const thumbBuffer = await sharp(fullPng)
      .extract({left, top, width: w, height: h})
      .resize(200)
      .toFormat('jpeg', {quality: 80})
      .toBuffer();

    const dataUri = `data:image/jpeg;base64,${thumbBuffer.toString('base64')}`;

    // This is what the new report should render instead of hot-link:
    console.log(`<img width="200" src="${dataUri}" alt="${el.src}" />`);
  }

  await browser.close();
})();
